async function displayClusterExtent(graphic) {
  const query = layerView.createQuery();
  query.aggregateIds = [graphic.getObjectId()];

  const { extent } = await layerView.queryExtent(query);
  const extentGraphic = {
    geometry: extent,
    symbol: {
      type: "simple-fill",
      outline: {
        width: 1.5,
        color: [75, 75, 75, 1],
      },
      style: "none",
      color: [0, 0, 0, 0.1],
    },
  };
  view.graphics.add(extentGraphic);
}

